#' Concatenate multiverse objects
#'
#' `c()` takes the union of the scenarios in several `pima.multi` objects.
#' The analytical choices within each object are left as they were generated by
#' `create_multi()`; choices from different objects are not crossed.
#'
#' @param ... Two or more `pima.multi` objects. Named arguments supply labels
#'   for the `.source` column; unnamed arguments are labelled `block1`,
#'   `block2`, and so on.
#' @param recursive Must be `FALSE`.
#'
#' @return A `pima.multi` object. Model and formula identifiers are reassigned
#'   so they are unique in the result. The `.source` column identifies the
#'   originating object. Specification columns absent from a block contain
#'   `NA` for its rows. All inputs must either have fitted models or have none.
#' @family multiverse construction
#' @export
#' @method c pima.multi
#'
#' @examples
#' a <- create_multi(
#'   Sepal.Width ~ Sepal.Length + Petal.Width,
#'   data = iris, focal = "Sepal.Length",
#'   fit.specs = list(lm = stats::lm)
#' )
#' b <- create_multi(
#'   Sepal.Width ~ Sepal.Length + Species,
#'   data = iris, focal = "Sepal.Length",
#'   fit.specs = list(lm = stats::lm)
#' )
#' both <- c(width = a, species = b)
#' both$scenarios
c.pima.multi <- function(..., recursive = FALSE) {
  if (!identical(recursive, FALSE)) {
    stop("`recursive` must be FALSE.", call. = FALSE)
  }

  objects <- list(...)
  if (!length(objects) || !all(vapply(objects, inherits, logical(1), "pima.multi"))) {
    stop("All inputs must be `pima.multi` objects.", call. = FALSE)
  }

  if (length(objects) == 1L) {
    return(objects[[1L]])
  }

  fitted <- vapply(objects, function(x) !is.null(x$models), logical(1))
  if (any(fitted) && !all(fitted)) {
    stop("All inputs must either contain fitted models or contain none.", call. = FALSE)
  }

  labels <- names(objects)
  if (is.null(labels)) labels <- rep("", length(objects))
  labels[!nzchar(labels)] <- paste0("block", which(!nzchar(labels)))
  labels <- make.unique(labels)

  scenario_parts <- vector("list", length(objects))
  formula_parts <- vector("list", length(objects))
  model_parts <- if (all(fitted)) vector("list", length(objects)) else NULL
  formula_offset <- 0L

  for (i in seq_along(objects)) {
    x <- objects[[i]]
    scenarios <- x$scenarios
    formulas <- x$formula_specs

    if (!all(c("model", "formula_id") %in% names(scenarios)) ||
        !all(c("formula_id", "calls") %in% names(formulas)) ||
        anyDuplicated(formulas$formula_id) ||
        anyNA(match(scenarios$formula_id, formulas$formula_id))) {
      stop("Input ", i, " has inconsistent scenarios or formula specifications.",
           call. = FALSE)
    }
    if (all(fitted) &&
        (length(x$models) != nrow(scenarios) ||
         !identical(names(x$models), as.character(scenarios$model)))) {
      stop("Input ", i, " has models that do not match its scenarios.", call. = FALSE)
    }

    new_formula_ids <- if (nrow(formulas)) {
      paste0("formula", formula_offset + seq_len(nrow(formulas)))
    } else {
      character()
    }
    scenarios$formula_id <- new_formula_ids[
      match(scenarios$formula_id, formulas$formula_id)
    ]
    formulas$formula_id <- new_formula_ids
    formula_offset <- formula_offset + nrow(formulas)

    if (".source" %in% names(scenarios)) {
      scenarios$.source <- paste(labels[i], scenarios$.source, sep = "/")
      formulas$.source <- paste(labels[i], formulas$.source, sep = "/")
    } else {
      scenarios$.source <- rep(labels[i], nrow(scenarios))
      formulas$.source <- rep(labels[i], nrow(formulas))
    }
    scenario_parts[[i]] <- scenarios
    formula_parts[[i]] <- formulas
    if (all(fitted)) model_parts[[i]] <- x$models
  }

  scenarios <- .bind_pima_multi_rows(scenario_parts)
  formulas <- .bind_pima_multi_rows(formula_parts)
  scenarios$model <- if (nrow(scenarios)) {
    paste0("model", seq_len(nrow(scenarios)))
  } else {
    character()
  }

  models <- NULL
  if (all(fitted)) {
    models <- unlist(model_parts, recursive = FALSE, use.names = FALSE)
    if (is.null(models)) models <- list()
    names(models) <- scenarios$model
  }

  out <- list(
    scenarios = scenarios,
    models = models,
    formula_specs = formulas,
    k = nrow(scenarios),
    specification = list(components = lapply(objects, `[[`, "specification")),
    call = match.call()
  )
  class(out) <- c("pima.multi", "list")
  out
}

.bind_pima_multi_rows <- function(parts) {
  columns <- unique(unlist(lapply(parts, names), use.names = FALSE))
  parts <- lapply(parts, function(x) {
    missing <- setdiff(columns, names(x))
    x[missing] <- lapply(missing, function(name) rep(NA, nrow(x)))
    x[columns]
  })
  out <- do.call(rbind, parts)
  rownames(out) <- NULL
  out
}

.nelem_formula <- function(f){
  f <- as.formula(f)
  x <- formula.tools::rhs.vars(f)
  y <- formula.tools::lhs.vars(f)
  list(nx = length(x),
       ny = length(y))
}
